import { Effect } from "effect"

export interface ShipmentRow {
  readonly id: string
  readonly recipientName: string
  readonly postalCode: string
  readonly parcelCount: number
}

export interface DispatchItem {
  readonly shipmentId: string
  readonly destination: string
  readonly labelsRequired: number
}

export interface ShipmentRepository {
  readonly listReady: (
    warehouseId: string
  ) => Effect.Effect<ReadonlyArray<ShipmentRow>, Error>
}

const toDispatchItem = (shipment: ShipmentRow): DispatchItem => ({
  shipmentId: shipment.id,
  destination: `${shipment.recipientName} (${shipment.postalCode})`,
  labelsRequired: shipment.parcelCount
})

export const loadDispatchManifest = (
  repository: ShipmentRepository,
  warehouseId: string
): Effect.Effect<ReadonlyArray<DispatchItem>, Error> =>
  Effect.gen(function*() {
    return yield* repository.listReady(warehouseId).pipe(
      Effect.map((shipments) => shipments.map(toDispatchItem))
    )
  })
